public class Shape {
    public double getArea() {
        return 0;
    }
}

public class Square extends Shape {
    private double side;

    public Square(double side) {
        this.side = side;
    }

    @Override
    public double getArea() {
        return side * side;
    }
}

// elsewhere:
Square sq = new Square(4);
System.out.println(sq.getArea());
```

